ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_any_10"] = {
{"s11_a03_jar_is_down_two_inches_048","any",2,"reg=family,civilian|tmp=seasoned|day=40,400|mood=grim|world=building",{1,"Somebody's taking sugar a spoon at a time, a spoon don't show",2,"Then how do you know?",1,"Jar's down two inches and there ain't been a cake baked in this house since August"}},
{"s11_a03_hungry_question_049","any",2,"reg=rescue|tmp=seasoned|day=30,400|mood=warm",{1,"Woman asked me was it a sin, wanting more than her share",2,"And what did you say?",1,"Wanting ain't a sin, told her she'd asked me a hungry question and to go eat"}},
{"s11_a03_little_bit_sick_about_it_050","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=grim",{1,"Ada's got a private can of coffee in that desk drawer - I've seen it",2,"Ada's kept this camp fed four months",1,"I know it, so I'm gonna say nothing, and I'm gonna be a little bit sick about it"}},
{"s11_a03_nobody_gets_to_be_surprised_051","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=calm|world=door",{1,"Read it back so it's said out loud, head count first",2,"Nineteen, six can't work",1,"Days of food",3,"Nine, and water's the pinch, not the food",4,"Kids first, then watch, then all - Friday we cut coffee if the run's empty",1,"That's it, nail it on the door - nobody gets to be surprised"}},
{"s11_a03_till_they_quit_052","any",3,"reg=family,civilian|tmp=seasoned|day=80,400|mood=warm|world=door",{1,"Potatoes come up good, three rows, better than we planted for",2,"So what's that mean at the door?",1,"Sunday everybody eats till they quit, not till it's fair - till they quit",3,"Is that so?",1,"I'm sure - write it on the door in big letters so the kids can read it themselves"}},
{"s11_a04_eleven_to_four_001","any",3,"reg=civilian,family|tmp=seasoned|day=30,400|mood=angry",{1,"We voted, eleven to four",2,"Then it's settled and you can quit",1,"Them four are the four that do the fighting, so I don't care for the number",3,"Numbers is numbers",1,"Numbers is numbers till the shooting starts, and then it's them four again"}},
{"s11_a04_short_is_how_a_lynching_goes_002","any",3,"reg=civilian,rescue|tmp=seasoned|day=40,400|mood=grim|world=building",{1,"We done it proper, two spoke for him, two against, no cross-talk",2,"And then?",1,"Then Earl read off the paper what he done, and we took hands - took an hour",3,"An hour's a long while in a church basement",1,"It's meant to be long, short is how a lynching goes"}},
{"s11_a04_we_never_killed_him_003","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim|world=road",{1,"We gave him a canteen, a box of twenty-two and three days of food",2,"And the road",1,"And the road... we never killed him, we keep telling each other that"}},
{"s11_a04_hear_that_gate_004","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=sad",{1,"His wife stayed",2,"She stayed?",1,"Stayed and watched him walk off down that lane, I'll hear that gate a long while"}},
{"s11_a04_hope_to_god_im_wrong_005","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=fear",{1,"Somebody's telling him what gets said at this table",2,"You got an idea who?",1,"I got an idea, and I hope to God I'm wrong, 'cause I like her"}},
{"s11_a04_ask_the_first_one_first_006","any",3,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=grim",{1,"I wrote that rule, nobody goes out alone",2,"And?",1,"And I went out Tanner Road by myself Tuesday morning - so go on - say it",3,"What were you after out there?",1,"That's the second question - ask the first one first"}},
{"s11_a04_tomorrow_i_count_007","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|hour=16,5|mood=calm",{1,"Put it back tonight in the dark and nobody counts",2,"And tomorrow?",1,"Tomorrow I count"}},
{"s11_a04_counting_hands_008","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=fear",{1,"We all put our hands up and said the words",2,"So?",1,"He weren't listening to the words, he was counting hands, I watched his lips move"}},
{"s11_a04_take_the_road_your_pick_009","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=angry|world=road",{1,"Two weeks on the burn pile and the ditch",2,"For a gate left open",1,"For a gate left open at night - take the two weeks or take the road - your pick"}},
{"s11_a04_tally_back_twice_010","any",4,"reg=civilian,family|tmp=seasoned|day=30,400|mood=calm|world=fence",{1,"Question, once, one sentence, do we take in the four at the fence - that's it",2,"I'll speak for",3,"I'll speak against",4,"Two more and that's all, and no cross-talk or I'll shut it down",1,"Hands after, counted out loud, and I'll say the tally back twice"}},
{"s11_a04_ill_abide_by_it_011","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=grim",{1,"It went against you, Dovie, nine to seven",2,"I heard the count same as you",1,"I need you to say out loud you'll abide by it - that's how it's done here",2,"I'll abide by it, I think y'all are wrong and I'll abide by it",1,"That's all I asked for - thank you"}},
{"s11_a04_before_anybody_leaves_012","any",2,"reg=civilian,worker|tmp=seasoned|day=30,400|mood=calm|world=door",{1,"Vote's done, now somebody says who does it, before anybody walks out that door",2,"Why before?",1,"'Cause once we're all outside, the doing gets handed to whoever's slowest to leave"}},
{"s11_a04_paper_in_the_hat_013","any",3,"reg=civilian,family|tmp=seasoned|day=40,400|mood=angry|world=building",{1,"Do it on paper, fold it, put it in the hat, nobody knows",2,"Fourteen people, I can tell every hand in this room by the writing",1,"Then print it, big letters, like a kid",3,"Or we do hands and we look at each other while we do it",1,"That's how we lost Wanda - hands, I'd like the hat this time"}},
{"s11_a04_boy_thats_sweeping_014","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=fear",{1,"He knew about them beans before I told a soul but you and Nell",2,"Then it's me or it's Nell",1,"Or it's the boy that was sweeping, I keep forgetting the boy that's always sweeping"}},
{"s11_a04_youd_have_believed_him_faster_015","any",2,"reg=civilian,family|tmp=fresh,seasoned|day=40,400|mood=sad",{1,"It was me",2,"I know it was you",1,"He said he'd put my mother's name on the list - said it once, quiet, and never again",2,"And you believed him",1,"You'd have believed him too, you'd have believed him faster than I did"}},
{"s11_a04_he_keeps_his_boots_016","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim|world=building,inside,road",{1,"We can't keep him and we can't turn him loose to tell folks what we've got in here",2,"Then say the other thing - say it, since you been circling it twenty minutes",3,"Nobody in this basement is saying that - look at me, nobody is saying it",4,"Then it's the road, and we take his boots so he can't come back quick",1,"He keeps his boots, he keeps 'em or I'm not putting my name on this"}},
{"s11_a04_not_to_that_017","any",3,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim",{1,"Stand up, this is the finding - read it off, Ada",2,"Found that on the nineteenth he opened the west gate and carried out eleven cans",1,"That's the finding - you got anything to say to that?",3,"Not to that, to something else, maybe, not to that"}},
{"s11_a04_id_like_it_done_decent_018","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=sad",{1,"Who walks him to the gate",2,"I will",1,"You? You're the one he hit with the pipe",2,"I know what he done, somebody's got to do it decent and I'd like it done decent"}},
{"s11_a04_dont_stand_and_watch_019","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim",{1,"Shut it",2,"He ain't even to the turn yet",1,"Shut it, and quit standing there watching him - don't watch"}},
{"s11_a04_nothing_will_have_decided_020","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=grim",{1,"Eight and eight",2,"So what happens on eight and eight?",1,"Nothing happens, and by Friday, nothing will have decided it for us"}},
{"s11_a04_that_girl_knows_everything_021","any",3,"reg=family|tmp=seasoned|day=40,400|mood=warm|world=building",{1,"Callie once asked if she could vote. Ten years old",2,"Ten is ten",1,"Did the hens every morning and sat through the whole meeting without a peep",3,"I'd have let her raise her hand, even if it didn't count",1,"She'd have known. That girl noticed everything before I did"}},
{"s11_a04_then_youre_the_right_one_022","any",3,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim|world=building",{1,"Somebody's got to speak for him, somebody in this room",2,"Not me, he went through my sister's house in August",3,"I'll speak for him, I don't even like him",1,"Then you're the right one - sit down with him first and listen a while"}},
{"s11_a04_came_in_here_instead_023","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=sad|world=inside",{1,"Before anybody starts, I took the lard, two pound of it, Thursday night",2,"You could've put it back in the dark and nobody'd have counted",1,"I know, sat up thinking on that till about three, then I come in here instead"}},
{"s11_a04_said_flat_all_three_024","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim|world=road",{1,"We ain't voting on guilty, he says he done it and Ada wrote it down",2,"So what are we voting on",1,"What happens now, the road, the work detail, or the last thing",3,"Read all three in the same voice, then, don't lean us with your mouth",4,"Road - work detail, the last thing - there, all three, said flat"}},
{"s11_a04_see_how_long_it_takes_025","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=calm|world=door",{1,"Nine rules on that door and seven of 'em are in his handwriting",2,"He wrote 'em 'cause nobody else would",1,"Then let's write the last two together, in front of everybody, and see how long that takes"}},
{"s11_a04_sit_still_for_a_minute_026","any",2,"reg=rescue|tmp=seasoned|day=40,400|mood=calm",{1,"They asked me to open it with a prayer - I did",2,"Did it help any?",1,"Made everybody sit still a minute, that's most of what a prayer does in a room like that"}},
{"s11_a04_book_and_the_rifle_027","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=fear",{1,"Delbert's at the fence",2,"Delbert's supposed to be gone eleven weeks",1,"He's at the fence and he's got a kid with him - not his kid",3,"Lord God",1,"Somebody get the book and somebody get the rifle, and let's do this one right"}},
{"s11_a04_weather_and_beans_028","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=sad",{1,"We kept her on, every hand went up to keep her on",2,"That was kind of y'all",1,"Kind, and now nobody says a thing at that table but weather and beans"}},
{"s11_a04_put_em_on_the_shelf_029","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|hour=4,11|mood=warm|world=building",{1,"Three cans and a jar of honey turned up on the pantry floor this morning",2,"You going to look for who?",1,"I said nobody counts, I meant it - I'll put 'em on the shelf and shut my mouth"}},
{"s11_a04_anything_longer_030","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=calm",{1,"Say it with me, I'll take my turn, I'll say what I took - I won't go out alone",2,"That's it? That's the oath, all of it?",1,"That's it, anything longer and folks start agreeing to things they don't mean"}},
{"s11_a04_same_finding_same_sentence_031","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim",{1,"It's Weldon, that's the trouble - it's Weldon and everybody likes Weldon",2,"So we let it go this once",3,"We let it go, and the next one's a fella nobody likes and we hang him for less",4,"That's exactly it, same finding, same sentence, no matter whose face it is",1,"Then read the finding, same words as last time - Ada, don't soften a one of 'em"}},
{"s11_a04_everybody_seeing_him_in_it_032","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=grim",{1,"Two weeks on the ditch",2,"He's sixty-one years old",1,"Then he digs slow, the ditch ain't the point, everybody seeing him in it is the point"}},
{"s11_a04_put_it_in_your_book_033","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=angry",{1,"I ain't sitting on that, I'll pull a double watch instead - all week, if you want",2,"Everybody wants the watch instead",1,"Then you've learned something about people and you can put it in your book"}},
{"s11_a04_and_i_won_034","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|hour=16,5|mood=sad",{1,"We won it, eleven to seven",2,"You don't look like a man that won something",1,"Seven people are gonna eat supper across the table from me tonight - and I won"}},
{"s11_a04_not_a_hint_035","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|hour=16,5|mood=calm|world=door",{1,"Nine rules, I'll read 'em once and then they're yours to know",2,"Go on ahead",1,"Nobody out alone, sign the book, no fire after dark - and the door list isn't a suggestion"}},
{"s11_a04_everybody_heard_it_036","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=angry|world=vehicle",{1,"The church bus folks have been here five weeks - do they vote?",2,"They eat and they work - so yes",3,"They're eleven and we're fourteen, you see the arithmetic in that",4,"I see it - say the rest out loud, Junior, since you started it",1,"He don't have to, everybody heard it - hands for the bus folks voting"}},
{"s11_a04_thats_why_hes_my_brother_037","any",2,"reg=family|tmp=seasoned|day=40,400|mood=grim",{1,"You voted against your own brother",2,"I did",1,"In front of the whole room, with him sat right there in the second row",2,"He'd have done the same to me, that's why he's my brother and that's why I done it"}},
{"s11_a04_carry_it_in_038","any",3,"reg=family,civilian|tmp=seasoned|day=40,400|mood=grim|world=door,building",{1,"The Tandy girl says she seen him at the pantry door",2,"She's eight years old",1,"She's eight and she ain't got one reason on earth to lie about a door",3,"Not in that basement - get it off her out in the yard and carry it in"}},
{"s11_a04_quit_talking_about_it_039","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=calm",{1,"Question's one sentence, do we winter here or do we winter at the Kelso place",2,"Here's got a well - Kelso's got a basement and no well",3,"Here's got a wall we built - Kelso's got a wall we'd build over",1,"Two for, two against, that's all - hands in ten minutes, then we quit talking about it"}},
{"s11_a04_done_to_children_040","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=sad",{1,"His girls are still over in the annex, somebody's got to feed his girls",2,"Nobody voted to starve his girls",1,"Nobody voted to feed 'em either, that's how a thing gets done to children"}},
{"s11_a04_clean_of_the_count_041","any",2,"reg=rescue|tmp=seasoned|day=30,400|mood=calm",{1,"I don't vote on people, said so the first day I come here",2,"That's a luxury and you know it",1,"It's a rule, I'll be stitching whoever loses, and I want my hands clean of the count"}},
{"s11_a04_dont_nobody_cheer_042","any",4,"reg=civilian,family|tmp=seasoned|day=80,400|mood=calm",{1,"It went against him, first time ever",2,"Nine to six",3,"And he stood up and said he'd abide by it - same as anybody has to",4,"He said it, said it looking at the floor, but he said it out loud",1,"Then this is a real place now, that's what that was - don't nobody cheer"}},
{"s11_a04_ive_been_trapped_before_043","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=calm",{1,"New rule, any rule we make gets read out on Sunday for a month after",2,"Why a month?",1,"'Cause a rule nobody remembers is a snare, and I've been snared before"}},
{"s11_a04_thats_the_girl_i_married_044","any",2,"reg=family|tmp=seasoned|day=40,400|mood=warm",{1,"Odessa voted the other way from me, in front of the whole room, hand right up",2,"That bother you?",1,"About an hour it did, then I thought, well, she's her own woman, that's the girl I married"}},
{"s11_a04_one_for_what_we_take_045","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim|world=inside",{1,"Nobody told him, that's what I come in here to say",2,"Then how'd he know about them beans",1,"He's been reading the book, the book we all sign, every night after we're asleep",3,"Huh - well, that's my own fault, then, I made the book",4,"Then make two, one for what we take out and one for what we've got"}},
{"s11_a04_cant_think_of_nothing_046","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=sad|world=road",{1,"So he's on the road, and that's that",2,"That's that",1,"I'd like to say one true thing about it and I can't think of nothing - so - that's that"}},
{"s11_a04_everybodyll_vote_different_047","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=funny|world=road",{1,"We voted to move Sunday, then it come a gullywasher and took the low road out",2,"So the vote's dead",1,"Vote ain't dead, the road is, we'll vote again dry and everybody'll vote different"}},
{"s11_a04_the_hour_and_the_paper_048","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=angry|world=building",{1,"I want it read out, all of it - in the basement, with the paper and the hands",2,"Nobody's accusing you of anything, Roy",1,"Everybody's accusing me of everything and not saying it, I'd rather have the hour"}},
{"s11_a04_somebody_put_up_two_049","any",3,"reg=civilian,family|tmp=seasoned|day=40,400|mood=funny|world=building",{1,"There was fifteen hands up and there's fourteen of us in this house",2,"Count it again",1,"I counted three times, fifteen hands, fourteen people, somebody put up two",3,"Heh, which is funny, and I would still like to know who"}},
{"s11_a04_not_one_can_opened_050","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=sad|world=trees,road",{1,"We give him three days of food and the Echo Creek road",2,"And?",1,"Traders found him Sunday, two mile down, sat under a tree, food not touched",3,"Not touched",1,"Not one can opened, so we didn't kill him - we keep telling each other that"}},
{"s11_a04_if_i_wouldnt_sign_it_051","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|hour=16,5|mood=grim",{1,"Does it go in the book? What we decided about him tonight?",2,"Put it in, names, the date, the count",3,"Names? I don't want mine on that for somebody's grandchild to read out",4,"That's just why it goes in, if I wouldn't sign it, I oughtn't have voted it",1,"Say that again after a night's sleep, if you still mean it, we'll do it your way"}},
{"s11_a04_makes_it_a_real_rule_052","any",3,"reg=civilian,family|tmp=seasoned|day=80,400|mood=calm|world=road",{1,"Out of that whole mess we got exactly one new rule",2,"Which is?",1,"Nobody goes out on the road November to March, cold months, they sit in the smokehouse",3,"And who feeds 'em while they sit?",1,"We do, that's the part makes it a real rule and not a speech"}},
{"s11_a05_selling_raffle_tickets_001","any",3,"reg=family,civilian|tmp=seasoned|day=40,400|mood=fear|world=vehicle",{1,"Fella come up the drive on a motorcycle, polite as church, took his cap off",2,"And?",1,"Half our gas every Sunday and nobody gets hurt, said it like he was selling raffle tickets",3,"What did you answer him?",1,"Said I'd have to ask, he said that's fine, he'd be back Sunday - and he will be"}},
{"s11_a05_nobody_coughs_002","any",2,"reg=civilian,worker|tmp=seasoned,veteran|day=20,400|mood=grim|world=vehicle",{1,"They're on 31W walking south, both lanes full of 'em",2,"How many?",1,"Don't matter how many, nobody shoots, nobody cranks a truck, nobody coughs - sit down"}},
{"s11_a05_walk_backwards_003","any",3,"reg=family,civilian|tmp=seasoned,veteran|day=40,400|mood=grim",{1,"Middle of the Carver bridge - noon, two men each, rifles slung",2,"Slung how?",1,"Muzzle down, off the shoulder, hands empty where they can see 'em - my girl for their boy",3,"And if they show up with four?",1,"Then we're already wrong, we walk backwards and nobody fires first"}},
{"s11_a05_it_aint_the_number_004","any",2,"reg=family,worker|tmp=seasoned|day=40,400|mood=grim",{1,"They bring us seed corn and then they ask how many rifles we've got",2,"You tell 'em?",1,"I tell 'em a number, it ain't the number - same question every visit, different fella asking"}},
{"s11_a05_then_they_shoot_you_005","any",3,"reg=civilian,rescue|tmp=seasoned|day=20,200|mood=grim|world=road",{1,"Army's got the road shut at Ekron, here's how it goes and you listen",2,"I'm listening",1,"They wave you off first, then they shoot the road in front of you, then they shoot you",3,"That order every time?",1,"Every time I've seen it, which is twice - twice is plenty for me"}},
{"s11_a05_sums_about_beans_006","any",3,"reg=civilian,family|tmp=seasoned|day=40,400|hour=16,5|mood=sad",{1,"Nine of 'em out there past the wire, two are kids",2,"How can you tell in the dark?",1,"By how high the voices are, and here I stand doing sums about beans",3,"Somebody's got to do the sums",1,"Yeah, I hate myself a little tonight, and I'll get over it, which is worse"}},
{"s11_a05_i_can_taste_it_007","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=warm",{1,"Same bunch took our truck in August come up today with a ham - and an apology",2,"A ham",1,"Cured ham and a sack of onions, I want it to be true so bad I can taste it"}},
{"s11_a05_just_roy_now_008","any",2,"reg=civilian,rescue|tmp=veteran,seasoned|day=30,400|mood=sad",{1,"I'm Foxtrot-11 - was",2,"Was?",1,"Nobody's answered Foxtrot in eleven days, so I reckon I'm just Roy now"}},
{"s11_a05_got_a_monday_in_it_009","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim",{1,"So - Sunday, do we set five gallon at the end of the drive or don't we",2,"We set it out and they come back every Sunday from here to forever",3,"We don't set it out and they come back once, at night, with all of 'em",4,"Then we pay this Sunday and we're gone before the next one",1,"That's the first thing anybody's said today that's got a Monday in it"}},
{"s11_a05_four_hours_010","any",2,"reg=family,civilian|tmp=seasoned|day=30,400|mood=fear",{1,"Four hours they went by, I counted to three hundred and then I quit counting",2,"Anybody move?",1,"Nell's baby fussed and she put her hand over him and he never made a sound - four hours"}},
{"s11_a05_dont_be_brave_be_quick_011","any",3,"reg=family,civilian|tmp=seasoned|day=30,400|hour=7,18|mood=fear|world=water,road",{1,"Somebody's got to get down to the Whitis place before that road bunch does",2,"On foot? In the daylight?",1,"On the bicycle, along the creek, they've got three kids and no radio",3,"I'll go",1,"Take the whistle, one blast means turn around - don't be brave, be quick"}},
{"s11_a05_apologized_twice_012","any",2,"reg=rescue,civilian|tmp=seasoned|day=20,120|mood=sad",{1,"That boy on the roadblock was nineteen and his hands shook worse than mine",2,"He point it at you?",1,"Pointed it at the dirt by my feet and apologized - twice, then turned us back anyway"}},
{"s11_a05_dont_go_find_out_013","any",2,"reg=civilian,worker|tmp=seasoned|day=30,300|mood=grim|world=cars",{1,"Word is the line's thinning, fewer trucks up at the bridge than there was",2,"Thinning 'cause they won or thinning 'cause they left?",1,"Nobody's got an answer to that, and that's the truth of it - so don't go find out"}},
{"s11_a05_you_dont_get_to_do_this_weak_014","any",2,"reg=family|tmp=seasoned|day=40,400|mood=fear",{1,"Noon's in two hours",2,"I know what time it is",1,"Eat something, you'll want steady hands and you ain't eat since yesterday morning",2,"I'll eat after",1,"Eat now and eat after, you don't get to do this weak"}},
{"s11_a05_neither_one_said_a_word_015","any",2,"reg=family,civilian|tmp=seasoned|day=40,400|mood=warm",{1,"She walked to me, whole bridge, on her own feet, and she never looked back at 'em",2,"And their boy?",1,"Walked the other way, passed each other about the middle - neither one said a word"}},
{"s11_a05_same_rules_different_plan_016","any",3,"reg=family,civilian|tmp=seasoned|day=40,400|mood=grim|world=trees",{1,"They come with four, and one of 'em was up in the trees on the far side",2,"So what'd you do",1,"Walked backwards off that bridge like we said - nobody fired, nobody got nothing",3,"So she's still with them",1,"She's still with them - Thursday we go back with a different plan and the same rules"}},
{"s11_a05_takeover_with_a_handshake_017","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|hour=16,5|mood=angry|world=inside",{1,"That Zink Road bunch wants to put ten men in here - says we'd be stronger for it",2,"Ten men - we're fourteen",3,"Ten of theirs and fourteen of ours, and theirs are the ones with rifles in the barn",4,"Stronger my foot, it's a takeover with a handshake on it",1,"Then we tell 'em no, we tell 'em nice, and we double the watch tonight regardless"}},
{"s11_a05_i_know_the_difference_018","any",3,"reg=civilian,family|tmp=seasoned|day=40,400|mood=warm",{1,"We let 'em in, all nine of 'em",2,"That's nine days off the food",1,"Nine days off the food and a woman that can pull a baby out sideways - she's a midwife",3,"You didn't know that when you opened the gate",1,"No I didn't, I opened it over the kids and I got lucky - I know the difference"}},
{"s11_a05_what_i_had_to_give_em_019","any",2,"reg=civilian,rescue|tmp=seasoned|day=40,400|mood=sad|world=building",{1,"I told 'em there's a church at Little Bethel with a roof and a stove in it",2,"Is there?",1,"There's a roof, I don't know about the stove, it's what I had to give 'em"}},
{"s11_a05_boy_at_the_mailbox_020","any",2,"reg=family,civilian|tmp=seasoned|day=40,400|mood=fear|world=building",{1,"He didn't take his cap off this time",2,"No?",1,"No, and he brought a boy with a pump gun to stand at the mailbox while we talked"}},
{"s11_a05_two_ruts_and_a_prayer_021","any",2,"reg=worker,family|tmp=seasoned|day=40,400|mood=calm|world=vehicle",{1,"We drop them two big elms across the drive at the curve - no truck gets past that",2,"Neither does ours",1,"Ours goes out the field gate, it's two ruts and a prayer, but it goes"}},
{"s11_a05_never_blow_a_long_one_022","any",2,"reg=family,worker|tmp=seasoned|day=30,400|mood=calm",{1,"One blast, come home, two, stay put, three, they're inside the wire",2,"And if it's a long one?",1,"Long one means it's me and I'm hurt - don't nobody ever blow a long one for fun"}},
{"s11_a05_water_in_first_023","any",4,"reg=civilian,family|tmp=seasoned|day=30,400|mood=fear|world=vehicle,cars,building,road",{1,"If a crowd came up a county road toward us, how would we decide whether to stay?",2,"Coming toward us or only coming past?",1,"That's what we'd have to find out. Before choosing shelter or a drive out",3,"I'd rather find somewhere to shelter than gamble on a drive out. An engine can bring attention too",4,"And we'd have to check room, water, and a way out. Shelter isn't just a word for everybody fitting",1,"Water and a way out first. Then a plan people can actually follow, not one we shout at them"}},
{"s11_a05_dont_get_a_church_024","any",2,"reg=rescue|tmp=seasoned|day=40,400|mood=grim",{1,"They asked for the church, not the food - the building",2,"What for?",1,"Wouldn't say, a man that won't say what he wants a church for don't get a church"}},
{"s11_a05_like_a_christmas_025","any",2,"reg=worker,civilian|tmp=seasoned|day=30,300|mood=warm",{1,"Them Guard boys at the water plant traded fair, twelve gallon of diesel for four hens",2,"Four hens for twelve gallon?",1,"They been eating out of cans since the fourth - Sergeant looked at them hens like a Christmas"}},
{"s11_a05_stop_where_you_stand_026","any",2,"reg=civilian,worker|tmp=seasoned|day=30,400|mood=grim",{1,"Fella on that bridge hollers at you from a long way off - real long way",2,"And then?",1,"And then he don't holler twice, you hear a voice out there, you stop where you stand"}},
{"s11_a05_then_they_took_him_027","any",2,"reg=worker,civilian|tmp=seasoned|day=40,400|mood=fear|world=generator",{1,"They didn't want the food, looked right at it and walked on past",2,"So what'd they take?",1,"Took Orbry, asked which one of us could run a generator, and then they took him"}},
{"s11_a05_with_your_hands_empty_028","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim",{1,"They want a hundred rounds of thirty-thirty for him",2,"We've got sixty in this whole house",3,"Then we say sixty and we mean sixty, we don't pad the number to look strong",4,"Or we don't pay and we go take him back, and that's a fight we lose",1,"Sixty rounds and both hogs, somebody go say that to 'em with your hands empty"}},
{"s11_a05_dated_the_eleventh_029","any",2,"reg=civilian,family|tmp=seasoned|day=30,300|hour=4,11|mood=grim",{1,"Chopper dropped paper on the back field this morning, yellow sheets, hundreds",2,"What's it say?",1,"Says stay in your homes and await instruction, dated the eleventh of July"}},
{"s11_a05_quit_arguing_with_him_030","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=sad",{1,"That sergeant's still on the roadblock with two men and no orders since August",2,"Why don't he just leave?",1,"Says his relief's coming, says it flat, every time, I've quit arguing with him"}},
{"s11_a05_thats_not_neighborly_031","any",2,"reg=family,worker|tmp=seasoned|day=40,400|mood=grim",{1,"Third time this month they've asked about our well",2,"What about it?",1,"How deep, how many gallon an hour, has it got a hand pump - that ain't neighborly"}},
{"s11_a05_stood_there_like_a_fool_032","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=warm",{1,"Man on a bicycle stopped and told us Zink Road's blocked - then he rode on",2,"He want anything off you?",1,"Wouldn't take water, wouldn't give a name, I stood there in the drive like a fool"}},
{"s11_a05_say_it_was_the_ridge_033","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=fear|world=building",{1,"They knew about the smokehouse, walked straight at it in the dark",2,"Then somebody drew 'em a map",3,"Or they looked, you can see that roof off the ridge with a cheap pair of binoculars",4,"I'd sooner it was the ridge than a person - say it was the ridge",1,"I'd sooner too, we move the smokehouse, we watch the ridge, and we watch each other"}},
{"s11_a05_now_they_know_where_i_live_034","any",2,"reg=rescue|tmp=seasoned|day=40,400|mood=grim",{1,"They brought me a boy with a hole through his leg - their boy",2,"You fix him?",1,"I fixed him, he'll walk fine - now they know where I live and what I can do"}},
{"s11_a05_ive_kept_them_all_035","any",2,"reg=family,civilian|tmp=seasoned|day=60,400|mood=grim",{1,"Four Sundays now, five gallon at the end of the drive and a note under the can",2,"A note?",1,"Thank you, it says - in pencil, same hand every week, I've kept 'em all and I can't say why"}},
{"s11_a05_louder_than_us_036","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=fear|world=road",{1,"They went right on past, never turned up the drive at all",2,"Why not?",1,"Something up the road was louder than us, I'd like to know what, and I wouldn't"}},
{"s11_a05_flinches_at_a_diesel_037","any",2,"reg=civilian,rescue|tmp=seasoned|day=60,400|mood=sad",{1,"They give Orbry back",2,"Alive?",1,"Alive - thin, won't talk about the four days and he flinches at a diesel motor"}},
{"s11_a05_dont_you_be_brave_038","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=fear|world=cars,stairs,building",{1,"What would we do if trucks pulled up after dark?",2,"I'd want somewhere to get out of sight",3,"Not somewhere we couldn't get out again. A cellar could trap us",4,"We'd need to check the exits and agree where everybody goes. Nobody fires just because they're frightened",1,"And nobody stays outside trying to be brave. That's the part I'd want said twice"}},
{"s11_a05_friends_of_everybody_dangerous_039","any",2,"reg=family,worker|tmp=seasoned|day=40,400|mood=angry",{1,"Old boy up Rickard Hollow's making liquor and trading it to everybody with a gun",2,"That's a business",1,"That's a business that makes friends of everybody dangerous inside ten mile of my kids"}},
{"s11_a05_got_back_on_the_mower_040","any",2,"reg=worker,civilian|tmp=seasoned|day=30,300|mood=funny|world=vehicle,road",{1,"There's a state road crew still working, orange truck, three men, cutting the shoulder",2,"Clearing it for who, exactly?",1,"I asked him that, fella said it's his job - then he got back on the mower"}},
{"s11_a05_gave_us_his_canteen_041","any",2,"reg=rescue,family|tmp=seasoned|day=20,120|mood=sad",{1,"We carried that child two mile to the roadblock and they turned us back",2,"With a sick kid?",1,"Lieutenant come out, looked at her, said he had no authority - then he give us his canteen"}},
{"s11_a05_came_at_suppertime_042","any",2,"reg=family|tmp=seasoned|day=40,400|mood=angry|world=door",{1,"He said all that with my children stood in the doorway behind me",2,"On purpose",1,"Well sure, he picked suppertime and came right up the drive"}},
{"s11_a05_say_it_back_everybody_043","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim",{1,"Rule or no rule, do we ever fire first",2,"No, never, that's how a county turns into a war",3,"Somebody's coming up that drive one day meaning it, and we'll be principled and dead",4,"Then what's the tell, what makes us fire?",1,"Long gun off the shoulder and pointed, that's the tell - say it back, everybody"}},
{"s11_a05_nobody_shoots_him_044","any",3,"reg=civilian,family|tmp=seasoned|day=30,300|mood=grim|world=fence",{1,"There's a boy in green at the fence with no rifle and no boots on",2,"No boots?",1,"Says he walked off the line at Valley Station six days back - asking for water, not a bed",3,"Give him both",1,"I aim to, I'm telling y'all first so nobody shoots him walking to the pump"}},
{"s11_a05_theyre_in_this_kitchen_045","any",2,"reg=family,civilian|tmp=seasoned|day=40,400|mood=angry|world=building",{1,"Ever since Sunday everybody in this house is short with everybody",2,"That's the raiders doing that",1,"That's the raiders doing it for free, they ain't even here and they're in this kitchen"}},
{"s11_a05_half_a_mile_off_for_us_046","any",2,"reg=family,civilian|tmp=seasoned|day=40,400|mood=warm",{1,"The Whitis dog started up about two and that's the only reason we was on our feet",2,"Their dog",1,"Their dog, half a mile off, for us, I carried them a sack of cornmeal in the morning"}},
{"s11_a05_not_one_word_about_it_047","any",4,"reg=civilian,family|tmp=seasoned|day=60,400|mood=grim",{1,"We turned nine people off in the dark last month - now we're asking Whitis for help",2,"That's a different thing",3,"Same thing, just us on the other end of it",4,"Then say that to 'em - straight out, and take whatever answer they give",1,"Yeah, and if the answer's no, we don't say one word about it - not one word"}},
{"s11_a05_hand_on_the_mic_048","any",2,"reg=civilian,rescue|tmp=seasoned|day=40,400|hour=4,11|mood=sad",{1,"Roy answered Foxtrot this morning, somebody called it and he answered it",2,"Who called it?",1,"Don't know, he sat with his hand on that mic about a minute before he keyed it"}},
{"s11_a05_nobody_talks_049","any",2,"reg=worker,civilian|tmp=seasoned|day=20,200|mood=calm",{1,"Them boys at the blockade will trade for eggs, they ain't supposed to",2,"Then how's it done?",1,"Walk up, set the basket on the line, step back - one comes and gets it - nobody talks"}},
{"s11_a05_how_bad_it_is_050","any",2,"reg=family,worker|tmp=seasoned|day=40,400|mood=sad",{1,"That fella with the cap, I know him, hauled hay for my daddy in eighty-seven",2,"You positive?",1,"I'm sure, and he knew me, and he never let on, and that's how I know how bad it is"}},
{"s11_a05_put_sundays_date_in_the_book_051","any",4,"reg=family,civilian|tmp=seasoned|day=60,400|hour=16,5|mood=angry|world=building",{1,"Sunday they didn't ask for gas, they asked for two of the girls to come work for 'em",2,"Work",3,"Say the real word, somebody in this room say the real word out loud",4,"Then that's the end of paying - get everything out of that smokehouse tonight",1,"Everything out tonight - Ada, put Sunday's date in the book and what they asked for"}},
{"s11_a05_both_jobs_go_together_052","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=grim",{1,"Two of theirs in the drive and one of ours in the side yard",2,"Which one of ours",1,"Orbry, second time they got him and this time they kept him",3,"Aw, hell",1,"Yeah, somebody get the shovels and somebody get Ada - both them jobs go together now"}},
{"s11_a06_dont_ask_me_to_pick_001","any",2,"reg=civilian,rescue|tmp=seasoned|day=40,400|mood=grim",{1,"He's the only man in this county that can stitch you",2,"And he's the reason the Pruitt girl's buried out back of the shed",1,"Both - at once, that's just how it is, and don't ask me to pick one"}},
{"s11_a06_a_man_that_guessed_002","any",2,"reg=rescue,civilian|tmp=seasoned|day=40,400|mood=sad",{1,"What did he actually do to her?",2,"Gave her what he had, it was the wrong thing and he knew he was guessing",1,"Then he ain't a murderer, he's a man that guessed",2,"Go tell that to her daddy - I did, it don't help"}},
{"s11_a06_he_wants_a_witness_003","any",2,"reg=rescue,family|tmp=seasoned|day=40,400|mood=grim",{1,"He come to me last night and asked would I sit in while he works on Nell",2,"Why you?",1,"He wants a witness - don't want to be alone in a room with somebody's wife again"}},
{"s11_a06_he_was_a_veterinarian_004","any",2,"reg=civilian,worker|tmp=seasoned|day=30,400|mood=calm",{1,"He ain't a doctor - y'all know that, right? Man's a veterinarian",2,"He put my shoulder back in",1,"I ain't saying he's no good, I'm saying we call him doctor 'cause it's easier on us"}},
{"s11_a06_go_boil_the_water_005","any",4,"reg=civilian,rescue|tmp=seasoned|day=40,400|mood=grim|world=building",{1,"It's got to come out of her and his are the only hands we've got",2,"Then he does it",3,"He does it, and if it goes bad, nobody in this house says one word to him - agreed?",4,"Nobody says a word out loud, that's the most you'll get and you know it",1,"That's what I'm asking for - out loud - go boil the water"}},
{"s11_a06_two_already_have_006","any",2,"reg=civilian,worker|tmp=seasoned|day=40,300|mood=grim|world=fence",{1,"Corn's knee high inside that fence, prettiest thing in the county right now",2,"So we trade 'em for some",1,"A man will die over six ears of that corn - two already have"}},
{"s11_a06_age_aint_the_thing_007","any",2,"reg=civilian,family|tmp=seasoned|day=40,300|mood=grim",{1,"Two old brothers own that garden, both near eighty, both sit out with shotguns",2,"Eighty years old",1,"Eighty, and they'll do it, age ain't the thing that makes a man hesitate"}},
{"s11_a06_wont_take_a_piss_008","any",2,"reg=civilian,rescue|tmp=seasoned|day=40,400|mood=funny|world=road",{1,"Brother Stiles said back in July that road would shut, and it shut",2,"That was a guess",1,"A guess that come true, now folks won't take a piss without asking him first"}},
{"s11_a06_theres_a_word_for_that_man_009","any",2,"reg=rescue|tmp=seasoned|day=40,400|mood=grim",{1,"I need y'all to quit asking me things I don't know the answer to",2,"You been right, though, twice you been right",1,"I been lucky, there's a word for a man who lets folks call luck something else"}},
{"s11_a06_before_you_hand_it_to_ray_010","any",2,"reg=civilian,worker|tmp=seasoned|day=30,400|mood=grim",{1,"Whoever's holding that microphone writes down what happened here",2,"It's a radio, not a book",1,"It's the only book there is now - think on that before you hand it to Ray"}},
{"s11_a06_thats_the_version_011","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=angry",{1,"He told it on the air like the whole house voted for it",2,"We didn't vote for it",1,"I know we didn't, three counties heard that we did, and now that's the version"}},
{"s11_a06_what_about_the_grave_012","any",3,"reg=family,civilian|tmp=seasoned|day=60,400|mood=sad",{1,"Darlene walked in Tuesday",2,"Darlene's dead, we buried her in June",1,"We buried a coat with her name sewed in it - so - what do we do about the grave?",3,"That's the question you're leading with?",1,"It's the one I can carry, the other one I can't hold onto yet"}},
{"s11_a06_likes_to_see_the_sky_013","any",2,"reg=family,civilian|tmp=seasoned|day=60,400|mood=sad|world=vehicle",{1,"She won't sleep in the house, sleeps in the truck bed with the tailgate down",2,"You ask her why?",1,"Said she likes to see the sky, said it in a way I didn't ask twice about"}},
{"s11_a06_i_said_i_would_so_014","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=grim",{1,"Bit at four, it's near on seven now",2,"Who's sitting with him?",1,"I am, he asked me to sit with him and I said I would, so"}},
{"s11_a06_thats_what_he_gets_015","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=sad",{1,"He wants his brother told it was quick",2,"It ain't going to be quick",1,"Then I'll tell his brother it was quick, that's what he asked for, that's what he gets"}},
{"s11_a06_walk_back_with_me_016","any",4,"reg=civilian,family|tmp=seasoned|day=30,400|hour=16,5|mood=grim",{1,"He's asking for it done before dark, and he's asking one of us to do it",2,"Then he can do it himself",3,"He tried, sat out there two hours with it in his lap and come back in the house",4,"So it's one of us - fine, we do it the way we said and nobody talks about who",1,"I'll do it, I'd like somebody to walk out with me and then walk back with me"}},
{"s11_a06_at_the_mailbox_not_the_house_017","any",2,"reg=civilian,rescue|tmp=seasoned|day=60,400|mood=grim|world=building",{1,"That's twice now, we patch somebody up and they come back with friends",2,"So we quit patching people up?",1,"No, we patch 'em at the mailbox, not at the house - that's the change, that's all"}},
{"s11_a06_not_by_accident_018","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=angry",{1,"The woman we took in back in September left the west gate on the latch",2,"By accident, maybe",1,"She tied a rag on the post, too - so, no, not by accident",3,"Where's she at now?",1,"Gone, took nothing with her, that's what's got me at this table at four in the morning"}},
{"s11_a06_a_real_fuss_with_a_cake_019","any",4,"reg=civilian,family|tmp=seasoned|day=60,400|mood=calm",{1,"New folks don't get the gate, the book or the well for thirty days",2,"Thirty days is a long while to be a guest in a place",3,"It's shorter than burying somebody",4,"Then say it to their faces day one - don't let 'em think they earned it and lost it",1,"Agreed, and on day thirty somebody makes a fuss over 'em - a real fuss, with a cake"}},
{"s11_a06_id_sleep_worse_than_he_does_020","any",2,"reg=rescue,civilian|tmp=seasoned|day=40,400|mood=grim",{1,"He keeps what's left of the medicine in a tackle box under his cot",2,"Under his cot",1,"Where would you keep it, I'd keep it under mine, and I'd sleep worse than he does"}},
{"s11_a06_coward_thats_probably_right_021","any",3,"reg=rescue,family|tmp=seasoned|day=40,400|mood=angry",{1,"He won't cut on the Tandy boy",2,"Why the hell not?",1,"Says he'd be guessing again, and the last guess is in the ground behind that shed",3,"So the boy just goes on hurting",1,"Boy goes on hurting and the doctor goes on being a coward that's probably right"}},
}
